#!/usr/bin/env node
/**
 * Sync the generated prototypes of codegen-x/ui8kit (packages/prototypes/out) into packages/blocks/src/generated.
 * The source is pinned by codegen.lock.json (repo, commit, path, target, sha256 of out/manifest.json); every file is
 * verified against the sha256 the manifest lists before it is copied. Never edit packages/blocks/src/generated by hand.
 *
 *   node --experimental-strip-types scripts/sync-codegen.ts                  # sparse clone at lock.commit, verify, copy
 *   node --experimental-strip-types scripts/sync-codegen.ts --update <ref>   # pin a new commit (sha or branch), then sync
 *   node --experimental-strip-types scripts/sync-codegen.ts --check          # CI: target == manifest == lock, and == upstream
 *   node --experimental-strip-types scripts/sync-codegen.ts --check --offline  # the same without the upstream fetch
 */
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

type Lock = { repo: string; commit: string; path: string; target: string; manifest: string };
type Manifest = { generator: string; version: number; items: Array<{ item: string }>; files: Record<string, string> };

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const LOCK = join(ROOT, "codegen.lock.json");
const args = process.argv.slice(2);
const check = args.includes("--check");
const offline = args.includes("--offline");
const updateAt = args.indexOf("--update");
const update = updateAt >= 0 ? args[updateAt + 1] : undefined;
if (updateAt >= 0 && !update) fail("--update needs a commit sha or a branch");

const sha256 = (bytes: Buffer | string): string => createHash("sha256").update(bytes).digest("hex");
function fail(message: string): never {
  console.error(`sync-codegen: ${message}`);
  process.exit(1);
}
const git = (cwd: string, ...a: string[]): string => execFileSync("git", a, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();

function walk(dir: string, base = dir): string[] {
  if (!existsSync(dir)) return [];
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...walk(p, base));
    else out.push(relative(base, p).split("\\").join("/"));
  }
  return out.sort();
}

/** The files of a tree against its manifest.json: every listed file has its sha256, nothing else is there. */
function verifyTree(dir: string, where: string): { manifest: Manifest; digest: string } {
  const file = join(dir, "manifest.json");
  if (!existsSync(file)) fail(`${where}: no manifest.json`);
  const raw = readFileSync(file);
  const manifest = JSON.parse(raw.toString("utf8")) as Manifest;
  const listed = Object.keys(manifest.files ?? {}).sort();
  if (listed.length === 0) fail(`${where}: the manifest lists no files`);
  const present = walk(dir).filter((f) => f !== "manifest.json");
  const problems: string[] = [];
  for (const f of listed) {
    const p = join(dir, f);
    if (!existsSync(p)) problems.push(`missing ${f}`);
    else if (sha256(readFileSync(p)) !== manifest.files[f]) problems.push(`sha256 differs: ${f}`);
  }
  for (const f of present) if (!(f in manifest.files)) problems.push(`not in the manifest: ${f}`);
  if (problems.length) fail(`${where}:\n  ${problems.join("\n  ")}`);
  return { manifest, digest: sha256(raw) };
}

/** Sparse, shallow, blob-filtered checkout of lock.path at `ref`; returns the directory and the resolved commit. */
function fetchAt(lock: Lock, ref: string): { dir: string; commit: string; cleanup: () => void } {
  const tmp = mkdtempSync(join(tmpdir(), "sync-codegen-"));
  const cleanup = () => rmSync(tmp, { recursive: true, force: true });
  try {
    git(tmp, "init", "-q");
    git(tmp, "remote", "add", "origin", lock.repo);
    git(tmp, "sparse-checkout", "set", "--no-cone", `/${lock.path}/`);
    git(tmp, "fetch", "-q", "--depth", "1", "--filter=blob:none", "origin", ref);
    git(tmp, "checkout", "-q", "FETCH_HEAD");
    const commit = git(tmp, "rev-parse", "HEAD");
    return { dir: join(tmp, lock.path), commit, cleanup };
  } catch (e) {
    cleanup();
    fail(`fetch ${lock.repo} ${ref}: ${(e as Error).message}`);
  }
}

const lock = JSON.parse(readFileSync(LOCK, "utf8")) as Lock;
for (const k of ["repo", "commit", "path", "target"] as const) if (!lock[k]) fail(`codegen.lock.json: no ${k}`);
const target = join(ROOT, lock.target);

if (check) {
  const local = verifyTree(target, lock.target);
  if (local.digest !== lock.manifest) fail(`${lock.target}/manifest.json sha256 ${local.digest} is not the locked ${lock.manifest}; run the sync`);
  if (!offline) {
    const up = fetchAt(lock, lock.commit);
    try {
      if (up.commit !== lock.commit) fail(`upstream resolved ${up.commit}, locked ${lock.commit}`);
      const remote = verifyTree(up.dir, `${lock.repo}@${lock.commit.slice(0, 12)}:${lock.path}`);
      if (remote.digest !== lock.manifest) fail(`upstream manifest sha256 ${remote.digest} is not the locked ${lock.manifest}`);
    } finally {
      up.cleanup();
    }
  }
  console.log(`sync-codegen: ${lock.target} matches ${lock.repo.replace(/\.git$/, "")}@${lock.commit.slice(0, 12)} (${Object.keys(local.manifest.files).length} files${offline ? ", offline" : ""})`);
  process.exit(0);
}

const up = fetchAt(lock, update ?? lock.commit);
try {
  if (!update && up.commit !== lock.commit) fail(`upstream resolved ${up.commit}, locked ${lock.commit}`);
  const src = verifyTree(up.dir, `${lock.repo}@${up.commit.slice(0, 12)}:${lock.path}`);
  if (!update && lock.manifest && src.digest !== lock.manifest) fail(`upstream manifest sha256 ${src.digest} is not the locked ${lock.manifest}`);
  rmSync(target, { recursive: true, force: true });
  mkdirSync(target, { recursive: true });
  for (const f of ["manifest.json", ...Object.keys(src.manifest.files)]) {
    mkdirSync(dirname(join(target, f)), { recursive: true });
    cpSync(join(up.dir, f), join(target, f));
  }
  verifyTree(target, lock.target);
  const next: Lock = { ...lock, commit: up.commit, manifest: src.digest };
  writeFileSync(LOCK, `${JSON.stringify(next, null, 2)}\n`);
  console.log(`sync-codegen: ${Object.keys(src.manifest.files).length} files from ${up.commit.slice(0, 12)} -> ${lock.target} (manifest ${src.digest.slice(0, 12)})`);
} finally {
  up.cleanup();
}
